import {shotSpec} from './shot-contract.js';
import {shotReady,independentReady,specMarkup,boundMarkup,bindShotControls,runIndependent} from './studio-shot-controls.js';
import {prepareElements,boardTools,bindBoardTools,generationSettings} from './studio-elements.js';
import {prepareWorkbenches,dialogueMarkup,bindDialogues,generateSpeech} from './studio-director.js';
