import {clone,uid,makeShots,boardReview,applyReport,validateReport,boardStale,changed,refs,validateRefs,invalidateChain,generationReady,makeVideoSnapshot,taskSnapshot,bindPreviousFrame,confirmBoard} from './workflow-store.js';
const kinds=['角色','场景','道具','站位'];
function promptHtml(sh){let out='',last=0;for(const m of sh.prompt.matchAll(/@\[([^\]]+)\]/g)){out+=esc(sh.prompt.slice(last,m.index));if(m[1]===sh.previousFrame?.id){out+=`<button class="mention" data-frame="${sh.id}">@上一视频尾帧${sh.previousFrameStale?' · 已过期':''}</button>`;last=m.index+m[0].length;continue;}const a=sh.assets.find(x=>x.id===m[1]);out+=a?`<button class="mention" data-mention="${esc(a.id)}" data-shot="${sh.id}">@${a.kind}·${esc(a.name)}</button>`:`<span class="error-text">失效图片引用</span>`;last=m.index+m[0].length;}return out+esc(sh.prompt.slice(last));}
function thumb(sh,a,index=0){return `<button class="reference-chip" style="--stack-index:${index}" title="${esc(a.name)} · ${a.confirmed?'已确认':a.image?'待确认':'未生成'}" data-asset="${a.id}" data-shot="${sh.id}">${a.image?`<img src="${esc(a.image)}" alt="${esc(a.kind+a.name)}">`:`<span class="reference-placeholder">${a.kind==='站位'?'↔':'＋'}</span>`}<span>${a.kind}<small>${a.confirmed?'已确认':a.image?'待确认':'未生成'}</small></span></button>`;}
export function boardPage(){const s=C.s,valid=!boardStale(s),confirmed=s.boardConfirmed===s.boardVersion&&!!s.shots.length;return `<div class="page-heading"><div><p class="eyebrow">共用步骤 / 分镜制作</p><h1>分镜工作台</h1><p>${s.shots.length?`${s.shots.length} 个镜头 · 分镜 v${s.boardVersion}`:'从已确认剧本生成镜头'} · 预计 ${s.shots.length?s.shots.reduce((n,sh)=>n+sh.duration,0):s.duration} 秒 · ${s.aspect||'画幅待设置'}</p></div>${s.final?'<button class="button" id="view-script">查看剧本</button>':''}</div>${boardTools()}${!s.final?'<section class="panel"><p>请先选定剧本。</p><a class="button primary" href="./script.html" data-nav="script">返回剧本</a></section>':`${!valid?'<div class="notice warning">剧本来源已更换，旧分镜保留，请重新生成。</div>':''}<div class="board-actions" id="board-toolbar"><div>${s.shots.length&&valid?`<span class="status-dot ${confirmed?'ok':''}"></span><span>${confirmed?'分镜已确认':s.report?.issues.length?'质检发现问题':'分镜待确认'}</span><button class="text-button" id="open-board-review">${s.report?'查看质检':'开始质检'}</button>`:''}</div><div class="row">${!s.shots.length||!valid?'<button class="button primary" id="generate-board">生成分镜</button>':`<details class="action-menu"><summary>分镜操作</summary><div><button id="add-shot-end">新增分镜</button><button id="regenerate-board">重新生成</button><button id="board-prompt-settings">生成提示词</button></div></details><button class="button" id="generate-assets" ${!confirmed?'disabled':''}>生成参考图</button>${s.shots.some(sh=>sh.assets.some(a=>a.image&&!a.confirmed))?'<button class="button" id="confirm-assets">检查参考图</button>':''}<select id="batch-mode" aria-label="视频生成方式"><option value="independent" ${s.chain.mode==='independent'?'selected':''}>独立 · 并行提交</option><option value="sequential" ${s.chain.mode==='sequential'?'selected':''}>按顺序 · 尾帧衔接</option></select><button class="button primary" id="batch-video" ${(s.chain.mode==='sequential'?!generationReady(s):!s.shots.some(sh=>independentReady(s,sh)))||s.chain.status==='running'?'disabled':''}>${s.chain.status==='paused'||s.chain.status==='failed'?'继续生成':s.chain.mode==='sequential'?'顺序生成视频':'批量并行生成'}</button>`}</div></div>${s.shots.length?`<section id="chain-state" class="chain-status" ${s.chain.status==='idle'?'hidden':''}><div><strong>${{running:'正在生成',completed:'本轮生成完成',paused:'已暂停',failed:s.chain.mode==='independent'?'部分镜头失败，可单独重试':'生成失败，后续已暂停',interrupted:'输入已变更，任务已暂停'}[s.chain.status]||'等待开始'}</strong><span>${esc(s.chain.message||'')}</span></div>${s.chain.status==='running'?'<button class="text-button" id="cancel-batch">暂停任务</button>':''}<details><summary>运行详情</summary><p class="helper">${s.chain.mode==='sequential'?'逐镜等待：视频完成 → 获取尾帧 → 作为下一镜参考。无有效尾帧时停止。':'各镜头独立使用已确认的参考图。'}</p><label class="check"><input id="fail-demo" type="checkbox" ${s.chain.failDemo?'checked':''}>演示下一镜失败</label><p class="helper">AI 视频及其尾帧为示意；上传的视频可尝试读取真实末帧。</p></details></section><div class="board-scroll" id="storyboard-table"><table class="board"><colgroup><col style="width:48px"><col style="width:205px"><col style="width:210px"><col style="width:345px"><col style="width:220px"><col style="width:70px"></colgroup><thead><tr><th>#</th><th>台词</th><th>角色 / 场景 / 道具 / 站位</th><th>视频提示词</th><th>视频</th><th>操作</th></tr></thead><tbody>${s.shots.map((sh,i)=>`<tr id="row-${sh.id}"><td>${i+1}</td><td>${dialogueMarkup(sh,i)}</td><td><div class="reference-windows">${kinds.map(kind=>`<section class="reference-window" data-reference-kind="${kind}"><div class="reference-window-label">${kind}<small>${sh.assets.filter(a=>a.kind===kind).length} 张</small></div><div class="reference-stack">${sh.assets.filter(a=>a.kind===kind).map((a,j)=>thumb(sh,a,j)).join('')||'<span class="helper">暂无图片</span>'}</div></section>`).join('')}</div></td><td><div class="prompt-rich" id="prompt-${sh.id}">${promptHtml(sh)}</div>${boundMarkup(s,sh)}<button class="text-button" data-edit-prompt="${sh.id}">编辑提示词 / 引用图片</button></td><td><div class="clip-preview" style="aspect-ratio:${shotSpec(s,sh).aspect.replace(':','/')}">${sh.video?.data?`<video controls src="${esc(sh.video.data)}"></video>`:sh.video?'<span>视频示例<br><small>非真实视频文件</small></span>':'<span>暂无视频</span>'}${sh.previousFrame?`<button class="video-frame-corner" data-frame="${sh.id}" aria-label="查看上一视频尾帧"><img src="${esc(sh.previousFrame.image)}" alt="上一视频尾帧"><span>${sh.previousFrameStale?'已过期':sh.previousFrame.kind==='demo'?'尾帧示例':'已取尾帧'}</span></button>`:''}</div>${specMarkup(s,sh)}${i>0?`<button class="text-button previous-frame-action" data-reference-previous="${sh.id}" ${!s.shots[i-1].video||s.shots[i-1].videoStale||s.chain.status==='running'?'disabled':''}>参考上一视频尾帧</button>`:''}${sh.videoStale?'<p class="error-text">输入已变，需更新</p>':''}<button class="text-button" data-video="${sh.id}" ${!shotReady(s,sh)||s.chain.status==='running'?'disabled':''}>${sh.video?'重新生成':'生成本镜'}</button></td><td><details class="action-menu row-menu"><summary aria-label="镜头 ${i+1} 更多操作">•••</summary><div><button data-add="${sh.id}">向下新增</button><button data-remove="${sh.id}" ${s.shots.length===1?'disabled':''}>删除镜头</button><button data-move="${sh.id}:-1" ${i===0?'disabled':''}>上移</button><button data-move="${sh.id}:1" ${i===s.shots.length-1?'disabled':''}>下移</button><button data-upload="${sh.id}">上传视频</button><button data-audio-settings="${sh.id}">音频模型配置</button></div></details></td></tr>`).join('')}</tbody></table></div><div class="section-end"><p class="helper">点击 @图片标签预览；图片改名不会破坏引用。生成前需确认分镜及四类参考图。</p><a class="button" href="./finishing.html" data-nav="finishing">成片与导出 →</a></div>`:'<div class="empty-inline">生成后自动质检，确认分镜再制作参考图、音频和视频。</div>'}`}`;}
export async function generateBoard(instruction=''){
 const s=C.s;if(!s.final)return toast('请先确认剧本');if(!s.generation?.aspect)return toast('请在生成设置中补齐项目规格');
 if(s.shots.length)s.history.push({boardVersion:s.boardVersion,scriptId:s.boardScriptId,shots:clone(s.shots)});
 s.shots=makeShots(s);s.shots.forEach((sh,i)=>{if(instruction.trim())sh.prompt+='\n本轮生成要求（演示）：'+instruction.trim();sh.dialogues=[{id:uid('line'),speaker:sh.speaker,emotion:sh.emotion,text:sh.dialogue,voice:'默认音色'}];if(i===0)sh.dialogues.push({id:uid('line'),speaker:'对方',emotion:'自然',text:'请进，我们慢慢说。',voice:'默认音色'});sh.dialogue=sh.dialogues.map(d=>d.speaker+'：'+d.text).join('\n')});
 prepareElements();s.boardVersion++;s.boardScriptId=s.final.id;s.boardConfirmed=0;s.chain={mode:'independent',status:'idle',next:0,runId:null};s.finishing.order=[];s.finishing.durations={};s.exported=false;
 logJob(s,'storyboard',{instruction,shots:s.shots});boardReview(s);logJob(s,'review',s.report);s.director.open.storyboard=true;save();C.render();
}
export function boardQualityMarkup(){
 const s=C.s,r=s.report;if(!s.shots.length)return '<p class="helper">生成分镜后自动显示质检建议。</p>';
 const expired=r&&(r.baseBoardVersion!==s.boardVersion||r.scriptId!==s.final?.id),issues=r?.issues||[];
 return `<section class="audit-compact" id="board-quality"><h3>分镜质检</h3><p class="notice ${!r||expired||issues.length?'warning':'success'}" id="board-qc-report">${!r?'当前版本暂无报告，仍可继续。':expired?'报告已过期，可重新检查或继续。':issues.length?issues.length+' 项示例建议：补齐动作衔接。':'示例复检完成，未返回待处理问题。'}</p>${!expired?issues.map(x=>`<details><summary>${esc(x.type)}</summary><p>${esc(x.evidence)}</p><p>建议：${esc(x.after.replace(/@\[[^\]]+\]/g,'@参考图'))}</p></details>`).join(''):''}<p class="helper">质检仅供参考，是否修改由你决定。</p>${!expired&&issues.length?'<button class="button" id="repair-board">按建议修改</button>':''}${s.boardConfirmed===s.boardVersion?'<p class="pill success">已选择当前分镜，可继续制作</p>':'<button class="button primary" id="approve-board">保留当前版本并继续</button>'}<small class="helper">修复另存新版；继续不会改变原质检结论。</small></section>`;
}
export function bindBoardQuality(){const s=C.s;on('repair-board',()=>{try{applyReport(s);logJob(s,'boardRepair',{shots:s.shots});boardReview(s);logJob(s,'review',s.report);save();C.render()}catch(e){toast(e.message)}});on('approve-board',()=>{try{confirmBoard(s);save();C.render()}catch(e){toast(e.message)}});}
export function showBoardReport(){const s=C.s;try{if(!s.shots.length)return;boardReview(s);logJob(s,'review',s.report);s.director.open.storyboard=true;save();C.render()}catch(e){toast(e.message)}}
function svgPreview(kind){const shapes={角色:'<circle cx="100" cy="46" r="22"/><path d="M54 126Q58 75 100 76Q142 75 146 126"/>',场景:'<path d="M26 70L100 22L174 70V132H26Z"/><path d="M85 132V90H116V132" fill="#d3ddd5"/>',道具:'<path d="M45 49L100 25L154 49V115L100 140L45 115Z"/><path d="M100 75V140M45 49L100 75L154 49" stroke="#d3ddd5" fill="none"/>',站位:'<circle cx="55" cy="68" r="19"/><circle cx="145" cy="68" r="19"/><path d="M77 68H121M113 62L121 68L113 74" stroke="#344d60" fill="none"/><rect x="26" y="110" width="148" height="15"/>'};return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="200" height="160"><rect width="200" height="160" fill="#d3ddd5"/><g fill="#344d60">${shapes[kind]||shapes.场景}</g><text x="100" y="154" font-size="10" text-anchor="middle" fill="#26394a">${kind} · 生成示意</text></svg>`);}
function assetDialog(shotId,assetId){const s=C.s,sh=s.shots.find(x=>x.id===shotId),a=sh.assets.find(x=>x.id===assetId);const d=modal(`${a.kind}参考图 · ${a.name}`,`<div class="asset-editor"><div class="asset-large">${a.image?`<img src="${esc(a.image)}" alt="${esc(a.kind+a.name)}">`:'尚未生成参考图'}</div><div><label class="field">名称<input id="asset-name" type="text" value="${esc(a.name)}"></label><label class="field">描述<textarea id="asset-desc">${esc(a.description)}</textarea></label><label class="field">上传已有图片<input id="asset-upload" type="file" accept="image/png,image/jpeg,image/webp"></label><p class="helper">演示单图上限 2 MB；仅保存在本浏览器。</p><button class="text-button" id="generate-one-image">AI 生成此图</button><label class="field">从当前项目资产引用<select id="library-pick"><option value="">选择已加入项目的图片</option>${(s.libraryAssets||[]).filter(x=>x.image).map(x=>`<option value="${x.id}">${esc(x.kind)} · ${esc(x.name)}</option>`).join('')}</select></label></div></div>`,`<button class="button" id="save-library-asset">存入资产库</button><button class="button" id="save-asset">保存描述</button><button class="button primary" id="select-asset" ${!a.image?'disabled':''}>确认选用</button>`);on('save-library-asset',()=>{const h=hub();const item={id:uid('library'),kind:a.kind==='站位'?'站位图':a.kind,name:a.name,description:a.description,image:a.image,version:1};h.assets.push(item);putHub(h);toast('已存入资产库，可跨项目复用')});if($('library-pick'))$('library-pick').onchange=e=>{const lib=(s.libraryAssets||[]).find(x=>x.id===e.target.value);if(!lib)return;a.image=lib.image;a.libraryAssetId=lib.id;a.libraryVersion=lib.version;a.version++;a.confirmed=false;invalidateChain(s,s.shots.indexOf(sh));save();d.close();assetDialog(shotId,assetId)};function hold(){const name=$('asset-name').value.trim();if(!name)throw Error('名称不能为空');if(name!==a.name||$('asset-desc').value!==a.description){a.name=name;a.description=$('asset-desc').value;a.version++;a.confirmed=false;invalidateChain(s,s.shots.indexOf(sh));}}
 on('save-asset',()=>{try{hold();save();d.close();C.render()}catch(e){toast(e.message)}});on('select-asset',()=>{try{hold();a.confirmed=true;save();d.close();C.render()}catch(e){toast(e.message)}});on('generate-one-image',()=>{try{hold();a.image=svgPreview(a.kind);logJob(s,'image',{assetId:a.id,kind:a.kind});a.version++;a.confirmed=false;invalidateChain(s,s.shots.indexOf(sh));save();d.close();C.render();assetDialog(shotId,assetId)}catch(e){toast(e.message)}});$('asset-upload').onchange=e=>readFile(e.target.files[0],2,['image/png','image/jpeg','image/webp'],data=>{a.image=data;a.version++;a.confirmed=false;invalidateChain(s,s.shots.indexOf(sh));save();d.close();C.render();assetDialog(shotId,assetId)});}
function readFile(f,mb,types,done){if(!f)return;if(!types.includes(f.type)||f.size>mb*1024*1024){toast(`文件类型不支持或超过 ${mb} MB 演示上限`);return}const reader=new FileReader();reader.onload=()=>done(reader.result);reader.onerror=()=>toast('读取失败，请重试');reader.readAsDataURL(f);}
function editPrompt(id){const sh=C.s.shots.find(x=>x.id===id);const human=sh.prompt.replace(/@\[([^\]]+)\]/g,(_,id)=>{if(id===sh.previousFrame?.id)return '@尾帧[上一视频]';const a=sh.assets.find(x=>x.id===id);return a?`@${a.kind}[${a.name}]`:'@失效引用';});const d=modal('编辑镜头提示词',`<label class="field">提示词<textarea id="mention-editor">${esc(human)}</textarea></label><div class="row"><select id="mention-select" aria-label="选择引用图片">${sh.assets.map(a=>`<option value="${a.id}">${a.kind} · ${esc(a.name)}</option>`).join('')}</select><button class="button" id="insert-mention">插入图片引用</button></div><p class="helper">使用选择器插入 @图片；保存后可直接点击标签预览。系统按固定图片 ID 关联，名称变化不影响已保存引用。</p><p id="mention-error" class="error-text"></p>`, '<button class="button primary" id="save-mention">保存提示词</button>');on('insert-mention',()=>{const a=sh.assets.find(x=>x.id===$('mention-select').value);const e=$('mention-editor');e.setRangeText(`@${a.kind}[${a.name}]`,e.selectionStart,e.selectionEnd,'end');e.focus()});on('save-mention',()=>{try{let text=$('mention-editor').value;if(!text.trim())throw Error('提示词不能为空');if(sh.previousFrame)text=text.replaceAll('@尾帧[上一视频]','@['+sh.previousFrame.id+']');text=text.replace(/@(角色|场景|道具|站位)\[([^\]]+)\]/g,(_,kind,name)=>{const matches=sh.assets.filter(a=>a.kind===kind&&a.name===name);if(matches.length!==1)throw Error('图片名称无法唯一匹配，请从选择器重新插入');return `@[${matches[0].id}]`;});if(text.replace(/@\[[^\]]+\]/g,'').includes('@')||refs(text).some(id=>!sh.assets.some(a=>a.id===id)&&id!==sh.previousFrame?.id))throw Error('存在未识别的图片引用，请从选择器插入');sh.prompt=text;sh.version++;changed(C.s,C.s.shots.indexOf(sh));save();d.close();C.render()}catch(e){$('mention-error').textContent=e.message}});}
async function lastFrame(video){if(video.kind==='demo')return {id:uid('frame'),sourceVideoId:video.id,kind:'demo',image:svgPreview('场景')};return new Promise((resolve,reject)=>{const el=document.createElement('video');el.muted=true;el.preload='auto';let done=false;const finish=(err,value)=>{if(done)return;done=true;clearTimeout(timer);el.removeAttribute('src');el.load();err?reject(err):resolve(value)};const timer=setTimeout(()=>finish(Error('视频尾帧读取超时')),7000);el.onloadedmetadata=()=>{if(!Number.isFinite(el.duration)||el.duration<=0){finish(Error('视频时长无效'));return}el.currentTime=Math.max(0,el.duration-.05)};el.onseeked=()=>{try{const canvas=document.createElement('canvas');canvas.width=el.videoWidth;canvas.height=el.videoHeight;if(!canvas.width)throw Error('视频帧为空');canvas.getContext('2d').drawImage(el,0,0);finish(null,{id:uid('frame'),sourceVideoId:video.id,kind:'captured',image:canvas.toDataURL('image/jpeg',.65)})}catch(e){finish(e)}};el.onerror=()=>finish(Error('视频无法解码，请替换后重试'));el.src=video.data;});}
export async function runVideos(mode,startAt=0,one=false){const s=C.s;if(mode==='independent'){try{return await runIndependent(startAt,one)}catch(e){toast(e.message);return}}if(!generationReady(s)){toast('请确认分镜、四类参考图及所有图片引用');return}const batchConfig=clone(s);const runId=uid('run');s.chain={...s.chain,mode,status:'running',runId,next:startAt,error:null};save();C.render();for(let i=startAt;i<(one?startAt+1:s.shots.length);i++){if(s.chain.runId!==runId)return;const sh=s.shots[i];s.chain.next=i;s.chain.message=`镜头 ${i+1}/${s.shots.length} · ${mode==='sequential'&&i>0?'等待前镜尾帧，随后生成':'生成视频中'}`;C.render();let snapshot;try{const previous=mode==='sequential'&&i>0?s.shots[i-1]:null;if(previous?.video&&!previous.video.lastFrame)previous.video.lastFrame=await lastFrame(previous.video);if(previous)bindPreviousFrame(s,sh.id,previous.video.lastFrame,{automatic:true});snapshot=makeVideoSnapshot({...batchConfig,shots:s.shots},sh,mode,previous);sh.previousFrameStale=false;await wait(850);if(s.chain.runId!==runId)return;if(s.chain.failDemo){s.chain.failDemo=false;throw Error(`镜头 ${i+1} 生成失败（演示），未提交后续镜头`)}const video={id:uid('video'),kind:'demo',mode,snapshot};video.lastFrame=await lastFrame(video);if(s.chain.runId!==runId)return;if(sh.video){sh.videoHistory??=[];sh.videoHistory.push(sh.video);}sh.video=video;sh.videoStale=false;logJob(s,'video',video);for(let j=i+1;j<s.shots.length;j++)if(s.shots[j].video?.mode==='sequential'||s.shots[j].previousFrame){s.shots[j].videoStale=true;s.shots[j].previousFrameStale=true;}s.chain.next=i+1;save();}catch(e){if(s.chain.runId!==runId)return;logJob(s,'video',{error:e.message,shotId:sh.id,snapshot},'失败');s.chain.status='failed';s.chain.error=e.message;s.chain.message=e.message;s.chain.next=i;save();C.render();return;}}s.chain.status='completed';s.chain.message=mode==='sequential'?'顺序完成；每个后续镜头绑定前镜视频及尾帧版本。':'已完成独立镜头生成示例。';save();C.render();}
export function bindBoard(){const s=C.s;prepareElements();bindBoardTools();bindDialogues();bindShotControls();if(s.pendingBoard&&s.final){s.pendingBoard=false;save();queueMicrotask(()=>generateBoard());}on('generate-board',()=>generateBoard());on('regenerate-board',()=>generateBoard());on('view-script',()=>modal('已确认剧本',`<p class="source-novel">${esc(s.final.text)}</p>`));on('open-board-review',showBoardReport);on('board-prompt-settings',()=>C.settings('prompts','storyboard'));on('generate-assets',()=>{s.shots.forEach(sh=>sh.assets.forEach(a=>{a.image=svgPreview(a.kind);logJob(s,'image',{assetId:a.id,kind:a.kind});a.version++;a.confirmed=false}));logJob(s,'image',{assets:s.shots.flatMap(sh=>sh.assets.map(a=>({id:a.id,kind:a.kind,version:a.version})))});invalidateChain(s,0);save();C.render();toast('四类参考图示例已生成，请检查并确认')});on('confirm-assets',()=>{const d=modal('检查全部参考图',`<div class="asset-review-grid">${s.shots.map((sh,i)=>`<section><h3>镜头 ${i+1}</h3><div class="reference-grid">${sh.assets.map(a=>`<div>${a.image?`<img src="${esc(a.image)}" alt="镜头${i+1}${a.kind}">`:'缺图'}<p>${a.kind} · ${esc(a.name)}</p></div>`).join('')}</div></section>`).join('')}</div><p class="helper">角色、场景、道具与站位共同用于视频生成。这里为示意图。</p>`,'<button class="button primary" id="approve-assets">确认这些参考图</button>');on('approve-assets',()=>{if(s.shots.some(sh=>sh.assets.some(a=>!a.image))){toast('请先补齐缺失参考图');return}s.shots.forEach(sh=>sh.assets.forEach(a=>a.confirmed=true));save();d.close();C.render()})});if($('batch-mode'))$('batch-mode').onchange=e=>{s.chain.mode=e.target.value;s.chain.next=0;save();C.render()};on('batch-video',()=>runVideos(s.chain.mode,['paused','failed'].includes(s.chain.status)?s.chain.next:0));on('cancel-batch',()=>{s.chain.runId=null;s.shots.forEach(sh=>{if(['排队','生成中'].includes(sh.videoTask))sh.videoTask='已暂停'});s.chain.status='paused';s.chain.message='保留已完成镜头；继续时从当前未完成镜头开始。';save();C.render()});if($('fail-demo'))$('fail-demo').onchange=e=>{s.chain.failDemo=e.target.checked;save()};document.querySelectorAll('[data-asset],[data-mention]').forEach(b=>b.onclick=()=>assetDialog(b.dataset.shot,b.dataset.asset||b.dataset.mention));document.querySelectorAll('[data-reference-previous]').forEach(b=>b.onclick=async()=>{const id=b.dataset.referencePrevious,i=s.shots.findIndex(sh=>sh.id===id),previous=s.shots[i-1];b.disabled=true;try{if(!previous?.video||previous.videoStale)throw Error('上一视频尚未生成或已过期');const video=previous.video;const frame=video.lastFrame||await lastFrame(video);bindPreviousFrame(s,id,frame);video.lastFrame=frame;save();C.render();toast(frame.kind==='demo'?'已绑定上一视频尾帧示例；上传视频可截取真实尾帧':'已截取并引用上一视频尾帧')}catch(e){toast(e.message);C.render()}});document.querySelectorAll('[data-frame]').forEach(b=>b.onclick=()=>{const sh=s.shots.find(x=>x.id===b.dataset.frame);modal('前一镜头的尾帧',`<div class="asset-large"><img src="${esc(sh.previousFrame.image)}" alt="前镜尾帧"></div><p>${sh.previousFrame.kind==='demo'?'演示尾帧，非真实视频截图':'从上传视频读取的末帧'}</p><p class="helper">绑定上一镜视频版本；改动前镜后，此引用需要更新。</p>`)});document.querySelectorAll('[data-edit-prompt]').forEach(b=>b.onclick=()=>editPrompt(b.dataset.editPrompt));document.querySelectorAll('[data-dialogue]').forEach(e=>e.onchange=()=>{const i=s.shots.findIndex(x=>x.id===e.dataset.dialogue),sh=s.shots[i];sh.dialogue=e.value;sh.version++;if(sh.audio)sh.audio.stale=true;changed(s,i);save();C.render()});function addAfter(index){const sh=clone(s.shots[index]||makeShots(s)[0]);sh.id=uid('shot');const map=new Map();sh.assets=sh.assets.map((a,j)=>{const id=`${sh.id}-asset-${j+1}`;map.set(a.id,id);return {...a,id,confirmed:false}});sh.prompt=sh.prompt.replace(/@\[([^\]]+)\]/g,(_,id)=>`@[${map.get(id)||id}]`);sh.video=null;sh.audio=null;if(sh.previousFrame)sh.prompt=sh.prompt.replaceAll('@['+sh.previousFrame.id+']','');sh.previousFrame=null;sh.previousFrameStale=false;sh.videoStale=false;sh.dialogue='';sh.dialogues=[{id:uid('line'),speaker:'角色',text:'',emotion:'自然',voice:'默认音色'}];s.shots.splice(index+1,0,sh);changed(s,index+1);save();C.render()};on('add-shot-end',()=>addAfter(s.shots.length-1));document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>addAfter(s.shots.findIndex(sh=>sh.id===b.dataset.add)));document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>confirm('删除此镜头？','旧分镜归档；删除后可重新质检，后续依赖尾帧的镜头标记待更新。',()=>{const i=s.shots.findIndex(sh=>sh.id===b.dataset.remove);s.history.push({boardVersion:s.boardVersion,shots:clone(s.shots)});s.shots.splice(i,1);changed(s,i);save();C.render()}));document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{const[id,delta]=b.dataset.move.split(':'),i=s.shots.findIndex(sh=>sh.id===id),j=i+Number(delta);[s.shots[i],s.shots[j]]=[s.shots[j],s.shots[i]];changed(s,Math.min(i,j));save();C.render()});document.querySelectorAll('[data-video]').forEach(b=>b.onclick=()=>runVideos('independent',s.shots.findIndex(sh=>sh.id===b.dataset.video),true));document.querySelectorAll('[data-tts]').forEach(b=>b.onclick=async()=>{b.disabled=true;await generateSpeech(s.shots.find(x=>x.id===b.dataset.tts));C.render()});document.querySelectorAll('[data-speak]').forEach(b=>b.onclick=()=>{if(!window.speechSynthesis){toast('当前浏览器不支持朗读');return}const sh=s.shots.find(x=>x.id===b.dataset.speak);speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(sh.dialogue);u.lang='zh-CN';speechSynthesis.speak(u);toast('正在使用浏览器朗读台词，不是模型生成音频')});document.querySelectorAll('[data-audio-settings]').forEach(b=>b.onclick=()=>C.settings('audio','voice'));document.querySelectorAll('[data-upload]').forEach(b=>b.onclick=()=>{const sh=s.shots.find(x=>x.id===b.dataset.upload);const d=modal('上传镜头视频','<label class="field">选择 MP4 / WebM<input type="file" id="video-file" accept="video/mp4,video/webm"></label><p class="helper">本地演示上限 3 MB；顺序生成下一镜前尝试读取此视频尾帧。</p>');$('video-file').onchange=e=>readFile(e.target.files[0],3,['video/mp4','video/webm'],data=>{invalidateChain(s,s.shots.indexOf(sh));sh.video={id:uid('upload'),kind:'upload',data,mode:'independent',snapshot:taskSnapshot(s,'video')};sh.videoStale=false;save();d.close();C.render()})});}
